{% set z = 'sklep_michal' %}
{% set weekdays = ['mon','tue','wed','thu','fri','sat','sun'] %}
{% set today = now().weekday() %}
{% set ns = namespace(windows=[], rules=0) %}
{% for s in states.switch if s.entity_id.startswith('switch.schedule_') and s.state == 'on' %}
{% if ('input_boolean.' ~ z ~ '_schedule_active') in s.attributes.get('entities', []) %}
{% set ns.rules = ns.rules + 1 %}
{% set days = s.attributes.get('weekdays', []) %}
{% set prev = (today + 6) % 7 %}
{% set current_day = 'daily' in days or weekdays[today] in days or ('weekend' in days and today >= 5) or ('workday' in days and today < 5) %}
{% set previous_day = 'daily' in days or weekdays[prev] in days or ('weekend' in days and prev >= 5) or ('workday' in days and prev < 5) %}
{% set actions = s.attributes.get('actions', []) %}
{% for slot in s.attributes.get('timeslots', []) %}
{% set i = loop.index0 %}
{% set parts = slot.split(' - ') %}
{% if i < actions|length and actions[i].get('service') == 'input_boolean.turn_on' and parts|length == 2 and parts[0]|regex_match('^[0-9]{2}:[0-9]{2}(:[0-9]{2})?$') and parts[1]|regex_match('^[0-9]{2}:[0-9]{2}(:[0-9]{2})?$') %}
{% set start = (parts[0][:2]|int) * 60 + (parts[0][3:5]|int) %}
{% set end = (parts[1][:2]|int) * 60 + (parts[1][3:5]|int) %}
{% if 0 <= start < 1440 and 0 <= end <= 1440 %}
{% if current_day and end > start %}{% set ns.windows = ns.windows + [(start, end)] %}{% endif %}
{% if current_day and end < start %}{% set ns.windows = ns.windows + [(start, 1440)] %}{% endif %}
{% if previous_day and 0 < end < start %}{% set ns.windows = ns.windows + [(0, end)] %}{% endif %}
{% endif %}
{% endif %}
{% endfor %}
{% endif %}
{% endfor %}
{% set enabled = states('input_boolean.schedule_enable_' ~ z) %}

<h2>Dnešní osa dne</h2>
{% if enabled == 'off' %}**Rozvrh je pozastavený.** Osa ukazuje uložené časy zapnutých pravidel.
{% elif enabled != 'on' %}**Stav rozvrhu je neověřený.**
{% endif %}

{% if ns.rules %}
<div><span>00:00</span> <span>06:00</span> <span>12:00</span> <span>18:00</span> <span>24:00</span></div>
<div>{% if enabled != 'on' %}<span></span>{% endif %}</div>
<p><strong>Komfort</strong> · zbytek dne útlum podle rozvrhu</p>

{% if ns.windows %}{% for start, end in ns.windows | unique | sort %}
- **{{ '%02d:%02d'|format(start // 60, start % 60) }} – {{ '%02d:%02d'|format(end // 60, end % 60) }}**
{% endfor %}{% else %}Dnes není naplánovaný komfort.{% endif %}
{% else %}Pro zónu není k dispozici zapnuté pravidlo Scheduleru.{% endif %}

<small>Ruční režim, přitopení nebo centrální režim mohou mít přednost.</small>

ha-card {
  --hp-accent: var(--ha-color-teal-60, #0e6760);
  --hp-soft: color-mix(in srgb, var(--hp-accent) 12%, var(--card-background-color, white));
  --hp-hot: var(--state-active-color, #b65c13);
  border-radius: 17px;
}
ha-markdown { padding: 13px 14px !important; }

