{% set days = s.attributes.get('weekdays', []) %}
{% set prev = (today + 6) % 7 %}
{% set current_day = 'daily' in days or weekdays[today] in days or ('weekend' in days and today >= 5) or ('workday' in days and today < 5) %}
{% set previous_day = 'daily' in days or weekdays[prev] in days or ('weekend' in days and prev >= 5) or ('workday' in days and prev < 5) %}
{% set actions = s.attributes.get('actions', []) %}
{% for slot in s.attributes.get('timeslots', []) %}
{% set i = loop.index0 %}
{% set parts = slot.split(' - ') %}
{% if i < actions|length and actions[i].get('service') == 'input_boolean.turn_on' and parts|length == 2 and parts[0]|regex_match('^[0-9]{2}:[0-9]{2}(:[0-9]{2})?$') and parts[1]|regex_match('^[0-9]{2}:[0-9]{2}(:[0-9]{2})?$') %}
{% set start = (parts[0][:2]|int) * 60 + (parts[0][3:5]|int) %}
{% set end = (parts[1][:2]|int) * 60 + (parts[1][3:5]|int) %}
{% if 0 <= start < 1440 and 0 <= end <= 1440 %}
{% if current_day and end > start %}{% set ns.windows = ns.windows + [(start, end)] %}{% endif %}
{% if current_day and end < start %}{% set ns.windows = ns.windows + [(start, 1440)] %}{% endif %}
{% if previous_day and 0 < end < start %}{% set ns.windows = ns.windows + [(0, end)] %}{% endif %}
{% endif %}
{% endif %}
{% endfor %}
{% endif %}
{% endfor %}
{% set enabled = states('input_boolean.schedule_enable_' ~ z) %}

ha-markdown-element > h2 { font-size: 18px; font-weight: 750; margin: 0 0 9px; line-height: 1.25; }
ha-markdown-element > div:has(> div:nth-child(2):last-child > strong) { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 8px; }
ha-markdown-element > div:has(> div:nth-child(2):last-child > strong) > div { min-width: 0; background: var(--hp-soft); border-radius: 10px; padding: 6px 9px; }
ha-markdown-element > div:has(> div:nth-child(2):last-child > strong) > div strong { display: block; font-size: clamp(18px, 4vw, 27px); line-height: 1.12; font-variant-numeric: tabular-nums; letter-spacing: -.035em; }
ha-markdown-element > div:has(> div:nth-child(2):last-child > strong) > div small, ha-markdown-element > p > span { color: var(--secondary-text-color); }
ha-markdown-element > p:has(> span) { margin: 8px 0 5px; font-size: 13px; font-weight: 650; line-height: 1.35; }
ha-markdown-element > div:has(> a:nth-child(2):last-child) { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 6px; margin-top: 6px; }
ha-markdown-element > div:has(> a:nth-child(2):last-child) a { display: flex; min-height: 44px; align-items: center; justify-content: center; padding: 0 4px; border: 1px solid var(--divider-color); border-radius: 10px; color: var(--primary-text-color); background: var(--hp-soft); text-align: center; text-decoration: none; font-size: 13px; font-weight: 700; }
ha-markdown-element > div:has(> a:nth-child(2):last-child) a:hover { text-decoration: underline; }
ha-markdown-element > div:has(> a:nth-child(2):last-child) a:focus-visible { outline: 2px solid var(--primary-color); outline-offset: 1px; }

ha-markdown-element > div:has(> span:nth-child(5):last-child) { display: flex; justify-content: space-between; gap: 2px; font-size: 11px; font-variant-numeric: tabular-nums; color: var(--secondary-text-color); }
ha-markdown-element > div:has(> span:nth-child(5):last-child) + div { height: 15px; border-radius: 8px; margin: 5px 0 8px; background-color: var(--divider-color); }
ha-markdown-element > div:has(> span:nth-child(5):last-child) + div:has(> span) { opacity: .45; }
ha-markdown-element > div:has(> span:nth-child(5):last-child) + div + p { margin: 8px 0; font-size: 13px; }
ha-markdown-element > div:has(> span:nth-child(5):last-child) + div + p strong { color: var(--primary-text-color); }

{% if ns.windows %}
ha-markdown-element > div:has(> span:nth-child(5):last-child) + div { background-image: {% for start, end in ns.windows %}linear-gradient(to right, transparent {{ start / 14.4 }}%, var(--hp-accent) {{ start / 14.4 }}%, var(--hp-accent) {{ end / 14.4 }}%, transparent {{ end / 14.4 }}%){% if not loop.last %}, {% endif %}{% endfor %}; }
{% endif %}
ha-markdown-element > div:has(> span:nth-child(5):last-child) > span { white-space: nowrap; }
ha-markdown-element > div:has(> span:nth-child(5):last-child) + div:empty::after { content: ''; }
